import type { Melody } from 'app/services/MelodiesService/types';

export interface ImportedTrack {
  id: string;
  name: string;
  melody: Melody;
  warnings: string[];
}

export interface ImportedSong {
  title: string;
  format: 'MIDI' | 'Guitar Pro';
  tracks: ImportedTrack[];
}

export interface RawImportNote {
  midi: number;
  start: number;
  duration: number;
}

export interface ImportRequest {
  name: string;
  data: ArrayBuffer;
}

export type ImportResponse = { song: ImportedSong } | { error: string };

export class MelodyImportError extends Error {}
export const MAX_IMPORT_BYTES = 10 * 1024 * 1024;
export const MAX_IMPORT_NOTES = 50000;
export const IMPORT_TIMEOUT_MS = 30000;
export const IMPORT_ACCEPT = '.mid,.midi,.gp3,.gp4,.gp5,.gpx,.gp';
