import { parseMusicFile } from './parse';
import { ImportRequest, ImportResponse, MelodyImportError } from './types';

const worker = globalThis as unknown as {
  onmessage: (event: MessageEvent<ImportRequest>) => void;
  postMessage: (response: ImportResponse) => void;
};
worker.onmessage = async ({ data: { name, data } }) => {
  try {
    worker.postMessage({ song: await parseMusicFile(name, data) });
  } catch (cause) {
    worker.postMessage({
      error:
        cause instanceof MelodyImportError
          ? cause.message
          : 'Не удалось прочитать файл. Возможно, он повреждён или использует неподдерживаемую версию.',
    });
  }
};
