import { ImportedSong, MAX_IMPORT_BYTES, MelodyImportError } from './types';

export const validateImportFile = (name: string, size: number) => {
  if (!/\.(mid|midi|gp3|gp4|gp5|gpx|gp)$/i.test(name))
    throw new MelodyImportError(
      'Выберите MIDI (.mid, .midi) или Guitar Pro (.gp3, .gp4, .gp5, .gpx, .gp).',
    );
  if (!size) throw new MelodyImportError('Выбранный файл пуст.');
  if (size > MAX_IMPORT_BYTES)
    throw new MelodyImportError(
      'Файл больше 10 МиБ. Выберите файл меньшего размера.',
    );
};

export const parseMusicFile = async (
  name: string,
  data: ArrayBuffer,
): Promise<ImportedSong> => {
  validateImportFile(name, data.byteLength);
  if (/\.(mid|midi)$/i.test(name)) {
    const { parseMidiFile } = await import('./midi');
    return parseMidiFile(new Uint8Array(data), name);
  }
  const { parseGuitarProFile } = await import('./guitarPro');
  return parseGuitarProFile(new Uint8Array(data), name);
};
